"use strict";
// Loads a module whose name is only known when the program runs: scriptc
// cannot compile that natively, so the package runs in a Node island.
const os = require(process.env.ISLANDSETS_OS_MODULE || "node:os");
const show = (v) => (v === null ? "<null>" : v === undefined ? "<undefined>" : `${typeof v}:${String(v)}`);

exports.eol = os.EOL.length;
exports.describeSet = (set) => `${set.size}:${[...set].map(show).join(",")}:${set.has(null)}:${set.has(undefined)}`;
exports.describeMap = (map) =>
  `${map.size}:${[...map].map(([k, v]) => `${show(k)}=${v}`).join(",")}:${map.get(null)}:${map.get(undefined)}`;
exports.hasNull = (set) => set.has(null);
exports.makeSet = () => new Set(["made", null]);
exports.makeMap = () =>
  new Map([
    [null, 1],
    [undefined, 2],
    ["made", 3],
  ]);
exports.addNull = (set) => {
  set.add(null);
};
exports.echo = (set) => set;
